def rata_rata_bergerak(data, n=5):
    hasil = []
    for i in range(len(data)):
        jendela = data[max(0, i - n + 1): i + 1]
        hasil.append(sum(jendela) / len(jendela))
    return hasil


def kontrol_kipas(menyala, suhu, batas=30.0, histeresis=1.0):
    if suhu > batas:
        return True
    if suhu < batas - histeresis:
        return False
    return menyala

