def adc_ke_suhu(adc, vref=3.3, bit=12, mv_per_c=10):
    volt = adc * vref / 2**bit
    return volt * 1000 / mv_per_c


class Termostat:
    def __init__(self, batas=30.0, histeresis=1.0, n=5):
        self.batas = batas
        self.histeresis = histeresis
        self.n = n
        self.data = []
        self.kipas = False

    def update(self, suhu):
        self.data.append(suhu)
        self.data = self.data[-self.n:]
        rata = sum(self.data) / len(self.data)
        if rata > self.batas:
            self.kipas = True
        elif rata < self.batas - self.histeresis:
            self.kipas = False
        return rata, self.kipas


def jalankan(daftar_suhu, **opsi):
    t = Termostat(**opsi)
    return [t.update(s)[1] for s in daftar_suhu]


def format_status(suhu, kipas):
    return f"Suhu {suhu:.1f} C | Kipas {'ON' if kipas else 'OFF'}"
